fn copy(arr: &Vec<i8>) -> Vec<i8> {
    // Allocate exactly enough capacity, then copy each element.
    let mut result: Vec<i8> = Vec::with_capacity(arr.len());
    for i in 0..arr.len() {
        result.push(arr[i]);
    }
    result
}

